// [Normalize alerts] Grafana 웹훅 payload → 알럿 1건당 1 item
// mode: runOnceForAllItems
const body = $input.first().json.body ?? {};
const alerts = body.alerts ?? [];

const BASE = '{app="alertlab", level="ERROR"}';

// 알럿 종류별로 "원인 로그" 를 찾는 Loki 쿼리를 다르게 잡는다
function lokiQueryFor(alertname, errorType) {
  switch (alertname) {
    case 'DbLockContention':
      return `${BASE} |~ "(?i)deadlock|lock wait timeout"`;
    case 'HikariPending':
      return `${BASE} |~ "Connection is not available"`;
    case 'AppErrorLog':
    case 'AppErrorBurst':
      return errorType ? `${BASE} | json | error_type="${errorType}"` : BASE;
    default:
      return BASE;
  }
}

// Grafana 는 알럿 규칙 프로비저닝 파일의 ${VAR} 를 치환하지 않으므로 여기서 채운다 (예: runbook_url)
const fillEnv = (annotations) =>
  Object.fromEntries(
    Object.entries(annotations).map(([k, v]) => [
      k,
      String(v).replace(/\$\{(GITHUB_OWNER|GITHUB_REPO)\}/g, (_, name) => $env[name] ?? ''),
    ]),
  );

return alerts.map((a) => {
  const labels = a.labels ?? {};
  const startsAt = a.startsAt ?? new Date().toISOString();
  return {
    json: {
      status: a.status, // firing | resolved
      alertname: labels.alertname ?? 'unknown',
      severity: labels.severity ?? 'minor',
      error_type: labels.error_type || 'app',
      service: labels.service ?? 'alertlab',
      labels,
      annotations: fillEnv(a.annotations ?? {}),
      startsAt,
      endsAt: a.endsAt,
      fingerprint: a.fingerprint,
      values: a.values ?? {},
      loki: {
        query: lokiQueryFor(labels.alertname, labels.error_type),
        start: new Date(Date.parse(startsAt) - 10 * 60 * 1000).toISOString(),
        end: new Date().toISOString(),
      },
    },
  };
});

// [Build resolved message] resolved 알럿은 LLM 분석 없이 짧은 해제 메시지만
// mode: runOnceForEachItem
const a = $json;
const kst = (iso) => new Date(iso).toLocaleString('sv-SE', { timeZone: 'Asia/Seoul' }); // yyyy-MM-dd HH:mm:ss

const text = `✅ *[RESOLVED] ${a.alertname}* (${a.severity}) — ${a.annotations.summary ?? ''}`;
return {
  json: {
    slack: {
      text,
      blocks: [
        { type: 'section', text: { type: 'mrkdwn', text } },
        {
          type: 'context',
          elements: [{ type: 'mrkdwn', text: `🕐 발생 ${kst(a.startsAt)} → 해제 ${kst(a.endsAt)}` }],
        },
      ],
    },
  },
};

// [Extract error context] Loki 로그 + 앱 커밋 SHA → 분석용 컨텍스트
// mode: runOnceForEachItem
const alert = $('Normalize alerts').item.json;
const loki = $('Query Loki').item.json;
const info = $('Get app info').item.json;

const OWNER = $env.GITHUB_OWNER;
const REPO = $env.GITHUB_REPO;
const PKG = 'com.example.alertlab.';

// ---- 1. 로그 중 스택트레이스가 있는 가장 최근 것 선택
const entries = [];
for (const stream of loki?.data?.result ?? []) {
  for (const [ts, line] of stream.values ?? []) {
    try {
      entries.push({ ts: Number(String(ts).slice(0, 13)), ...JSON.parse(line) });
    } catch (e) {
      // JSON 이 아닌 로그는 무시
    }
  }
}
entries.sort((x, y) => y.ts - x.ts);
const log = entries.find((e) => e.stack_trace) ?? entries[0] ?? null;

// ---- 2. 민감정보 마스킹 (외부 LLM 으로 나가기 전)
const mask = (s) =>
  String(s ?? '')
    .replace(/[\w.+-]+@[\w-]+\.[\w.]+/g, '<email>')
    .replace(/(Bearer\s+)[\w\-.=]+/gi, '$1<token>')
    .replace(/\b(sk|ghp|gho|github_pat|xox[abp])[-_][\w-]{10,}/g, '<secret>')
    .replace(/(password|passwd|pwd|secret|token)(["']?\s*[:=]\s*["']?)[^\s"',;]+/gi, '$1$2<masked>');

// ---- 3. 스택 축약: 상위 20줄 + 우리 패키지 프레임 + Caused by
const stackLines = String(log?.stack_trace ?? '').split('\n').map((l) => l.replace(/\r$/, ''));
const kept = [];
stackLines.forEach((l, i) => {
  const ours = l.includes(`at ${PKG}`) && !l.includes('$$');
  if (i < 20 || ours || l.startsWith('Caused by')) kept.push(l);
});
const stack = mask(kept.slice(0, 40).join('\n'));

// ---- 4. 우리 코드의 첫 프레임 → 파일 경로·라인
const frameRe = /at (com\.example\.alertlab\.[\w.$]+)\.([\w$<>]+)\(([\w$]+\.java):(\d+)\)/;
let frame = null;
for (const l of stackLines) {
  const m = l.match(frameRe);
  if (m && !m[1].includes('$$')) {
    const outerClass = m[1].split('$')[0];
    frame = {
      className: m[1],
      method: m[2],
      line: Number(m[4]),
      path: `src/main/java/${outerClass.replace(/\./g, '/')}.java`,
    };
    break;
  }
}

// ---- 5. 배포 커밋 SHA 로 고정한 링크 (SHA 가 없으면 main)
const commitId = info?.git?.commit?.id;
const sha = (typeof commitId === 'string' ? commitId : commitId?.full) || 'main';
const code = frame
  ? {
      ...frame,
      sha,
      raw_url: `https://raw.githubusercontent.com/${OWNER}/${REPO}/${sha}/${frame.path}`,
      permalink: `https://github.com/${OWNER}/${REPO}/blob/${sha}/${frame.path}#L${frame.line}`,
    }
  : null;

return {
  json: {
    ...alert,
    // 알럿 라벨에 error_type 이 없거나 부정확할 수 있으므로, 실제 로그에 기록된 값을 우선한다
    error_type: log?.error_type || alert.error_type,
    log: log && {
      time: log['@timestamp'],
      message: mask(log.message),
      logger: log.logger_name,
      traceId: log.traceId ?? null,
      method: log.method ?? null,
      requestURI: log.requestURI ?? null,
      error_type: log.error_type ?? null,
      stack,
    },
    log_count: entries.length,
    code,
  },
};

// [Build code snippet] GitHub 에서 받은 소스(실패 시 로컬 마운트 소스)에서 ±15줄 추출
// mode: runOnceForEachItem
const fs = require('fs');

const ctx = $('Extract error context').item.json;
const res = $json; // Fetch source 의 fullResponse: { statusCode, body }
const RADIUS = 15;

if (!ctx.code) {
  return { json: { ...ctx, code_snippet: null } };
}

let source = null;
let from = null;
if (res?.statusCode === 200 && typeof res.body === 'string') {
  source = res.body;
  from = 'github';
} else {
  // 아직 push 전이거나 SHA 가 GitHub 에 없을 때: compose 가 마운트한 로컬 src 사용
  try {
    source = fs.readFileSync(`/repo-src/${ctx.code.path.replace(/^src\//, '')}`, 'utf8');
    from = 'local';
  } catch (e) {
    source = null;
  }
}

let snippet = null;
if (source) {
  const lines = source.split('\n');
  const start = Math.max(1, ctx.code.line - RADIUS);
  const end = Math.min(lines.length, ctx.code.line + RADIUS);
  snippet = [];
  for (let n = start; n <= end; n++) {
    const marker = n === ctx.code.line ? '>>' : '  ';
    snippet.push(`${marker} ${String(n).padStart(4)} | ${lines[n - 1].replace(/\r$/, '')}`);
  }
  snippet = snippet.join('\n');
}

return { json: { ...ctx, code_snippet: snippet, code_source: from } };

// [Summarize DB diagnostics] 진단 쿼리 결과를 LLM 입력용 텍스트로 요약
// mode: runOnceForAllItems  (진단 결과는 DB 전체 상태라 알럿 수와 무관하게 한 번만 조회됨)
const rows = (name) =>
  $(name)
    .all()
    .map((i) => i.json)
    .filter((r) => r && Object.keys(r).length > 0);

const table = (title, list) =>
  list.length === 0
    ? `### ${title}\n(없음)`
    : `### ${title}\n` + list.map((r) => '- ' + JSON.stringify(r)).join('\n');

// SHOW ENGINE INNODB STATUS 에서 최근 데드락 섹션만 추출
const statusText = rows('Diag: innodb status')[0]?.Status ?? '';
const m = statusText.match(/LATEST DETECTED DEADLOCK\n-+\n([\s\S]*?)\n-{4,}\n[A-Z ]+\n-{4,}/);
const deadlock = m ? m[1].slice(0, 3000) : '(최근 감지된 데드락 없음)';

const summary = [
  table('실행 중인 쿼리 (information_schema.PROCESSLIST, Sleep 제외)', rows('Diag: processlist')),
  table('열린 트랜잭션 (information_schema.innodb_trx)', rows('Diag: innodb trx')),
  table('락 대기 관계 (performance_schema.data_lock_waits)', rows('Diag: lock waits')),
  table('인덱스 (alertlab 스키마)', rows('Diag: indexes')),
  `### 최근 데드락 (SHOW ENGINE INNODB STATUS)\n${deadlock}`,
].join('\n\n');

return $('Build code snippet')
  .all()
  .filter((i) => i.json.error_type === 'db')
  .map((i) => ({ json: { ...i.json, db_diagnostics: summary } }));

// [Build prompt] 시스템 프롬프트(파일) + 런북(파일) + 컨텍스트 → OpenAI 요청
// mode: runOnceForEachItem
const fs = require('fs');
const ctx = $json;

const read = (path) => {
  try {
    return fs.readFileSync(path, 'utf8');
  } catch (e) {
    return null;
  }
};

const systemPrompt = (read('/prompts/alert-analysis.md') ?? '').replace(/<!--[\s\S]*?-->/g, '').trim();
const runbook = read(`/runbooks/${ctx.alertname}.md`);
const kst = (iso) => new Date(iso).toLocaleString('sv-SE', { timeZone: 'Asia/Seoul' }); // yyyy-MM-dd HH:mm:ss

const user = [
  '## 알럿',
  `- 알럿명: ${ctx.alertname}`,
  `- severity: ${ctx.severity}`,
  `- error_type: ${ctx.error_type}`,
  `- 발생 시각(KST): ${kst(ctx.startsAt)}`,
  `- summary: ${ctx.annotations.summary ?? ''}`,
  `- description: ${ctx.annotations.description ?? ''}`,
  '',
  '## 에러 로그',
  ctx.log
    ? [
        `- 로그 시각: ${ctx.log.time}`,
        `- 요청: ${ctx.log.method ?? '-'} ${ctx.log.requestURI ?? '-'} (traceId=${ctx.log.traceId ?? '-'})`,
        `- 메시지: ${ctx.log.message}`,
        '- 스택트레이스(축약):',
        '```',
        ctx.log.stack,
        '```',
      ].join('\n')
    : '(알럿 시간대에 해당 에러 로그를 찾지 못함)',
  '',
  '## 관련 코드',
  ctx.code_snippet
    ? `${ctx.code.path}:${ctx.code.line} (${ctx.code.className}.${ctx.code.method})\n\`\`\`java\n${ctx.code_snippet}\n\`\`\``
    : '(없음)',
  '',
  '## DB 진단 결과',
  ctx.db_diagnostics ?? '(DB 관련 알럿이 아니어서 조회하지 않음)',
  '',
  '## 런북',
  runbook ?? '(없음)',
].join('\n');

// 출력 구조를 강제하는 JSON 스키마 (Structured Outputs)
const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['error_time', 'probable_causes', 'related_code', 'db_findings', 'recommended_actions', 'summary'],
  properties: {
    error_time: { type: 'string', description: 'KST, yyyy-MM-dd HH:mm:ss' },
    probable_causes: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['cause', 'confidence', 'evidence'],
        properties: {
          cause: { type: 'string' },
          confidence: { type: 'string', enum: ['high', 'medium', 'low'] },
          evidence: { type: 'string' },
        },
      },
    },
    related_code: {
      type: 'object',
      additionalProperties: false,
      required: ['file', 'line', 'explanation'],
      properties: {
        file: { type: 'string' },
        line: { type: 'integer' },
        explanation: { type: 'string' },
      },
    },
    db_findings: { type: 'string' },
    recommended_actions: {
      type: 'object',
      additionalProperties: false,
      required: ['immediate', 'permanent'],
      properties: {
        immediate: { type: 'array', items: { type: 'string' } },
        permanent: { type: 'array', items: { type: 'string' } },
      },
    },
    summary: { type: 'string' },
  },
};

return {
  json: {
    ctx,
    openai_request: {
      model: $env.OPENAI_MODEL || 'gpt-4.1-mini',
      max_completion_tokens: 1500,
      response_format: { type: 'json_schema', json_schema: { name: 'alert_analysis', strict: true, schema } },
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: user },
      ],
    },
  },
};

// [Build Slack message] LLM 분석 결과 + 컨텍스트 → Slack Block Kit
// mode: runOnceForEachItem
const ctx = $('Build prompt').item.json.ctx;
const res = $json;

let ai = null;
let aiError = null;
try {
  ai = JSON.parse(res.choices[0].message.content);
} catch (e) {
  aiError = res?.error?.message ?? 'LLM 응답을 해석하지 못했습니다.';
}

const SEV = {
  critical: { icon: '🔴', label: 'CRITICAL' },
  major: { icon: '🟠', label: 'MAJOR' },
  minor: { icon: '🟡', label: 'MINOR' },
};
const CONF = { high: '🟢 high', medium: '🟡 medium', low: '⚪ low' };
const sev = SEV[ctx.severity] ?? SEV.minor;
const kst = (iso) => new Date(iso).toLocaleString('sv-SE', { timeZone: 'Asia/Seoul' }); // yyyy-MM-dd HH:mm:ss
const cut = (s, n = 2900) => (s && s.length > n ? s.slice(0, n) + '…' : s);
const section = (text) => ({ type: 'section', text: { type: 'mrkdwn', text: cut(text) } });

const blocks = [];
blocks.push({
  type: 'header',
  text: { type: 'plain_text', text: `${sev.icon} [${sev.label}] ${ctx.alertname}`, emoji: true },
});
blocks.push(section(`*${ctx.annotations.summary ?? ''}*`));
blocks.push({
  type: 'section',
  fields: [
    { type: 'mrkdwn', text: `*🕐 에러 시간*\n${ai?.error_time || kst(ctx.log?.time ?? ctx.startsAt)}` },
    { type: 'mrkdwn', text: `*🏷️ 서비스 / 유형*\n${ctx.service} / ${ctx.error_type}` },
    { type: 'mrkdwn', text: `*🌐 요청*\n${ctx.log ? `${ctx.log.method ?? '-'} ${ctx.log.requestURI ?? '-'}` : '-'}` },
    { type: 'mrkdwn', text: `*🔎 traceId*\n\`${ctx.log?.traceId ?? '-'}\`` },
  ],
});
blocks.push({ type: 'divider' });

if (ai) {
  const causes = ai.probable_causes
    .map((c, i) => `${i + 1}. *${c.cause}*  (${CONF[c.confidence] ?? c.confidence})\n      ↳ 근거: ${c.evidence}`)
    .join('\n');
  blocks.push(section(`*🧐 추정 원인*\n${causes}`));
} else {
  blocks.push(section(`*⚠️ AI 분석 실패*\n${aiError}\n원본 로그: ${ctx.log?.message ?? '-'}`));
}

if (ctx.code) {
  const link = `<${ctx.code.permalink}|${ctx.code.path.split('/').pop()}:${ctx.code.line}>`;
  const around = (ctx.code_snippet ?? '')
    .split('\n')
    .filter((l) => {
      const n = Number(l.slice(2, 7));
      return Math.abs(n - ctx.code.line) <= 4;
    })
    .join('\n');
  const explain = ai?.related_code?.explanation ? `\n${ai.related_code.explanation}` : '';
  blocks.push(section(`*💻 관련 코드* ${link} — \`${ctx.code.method}()\`${explain}${around ? `\n\`\`\`${around}\`\`\`` : ''}`));
}

if (ctx.error_type === 'db' && ai?.db_findings) {
  blocks.push(section(`*🗄️ DB 진단*\n${ai.db_findings}`));
}

if (ai) {
  const list = (arr) => (arr.length ? arr.map((s) => `• ${s}`).join('\n') : '• -');
  blocks.push(
    section(
      `*🛠️ 권장 조치*\n*⚡ 즉시*\n${list(ai.recommended_actions.immediate)}\n*🔧 근본*\n${list(ai.recommended_actions.permanent)}`,
    ),
  );
  blocks.push(section(`*📝 분석 요약*\n${ai.summary}`));
}

const buttons = [];
const btn = (text, url) => url && buttons.push({ type: 'button', text: { type: 'plain_text', text, emoji: true }, url });
btn('📊 대시보드', ctx.annotations.dashboard_url);
btn('📜 로그 보기', ctx.annotations.grafana_explore_url);
btn('📘 런북', ctx.annotations.runbook_url);
btn('💻 코드', ctx.code?.permalink);
if (buttons.length) blocks.push({ type: 'actions', elements: buttons });

blocks.push({
  type: 'context',
  elements: [
    {
      type: 'mrkdwn',
      text: `🤖 n8n alert-analyzer · ${$('Build prompt').item.json.openai_request.model} · 코드 출처: ${ctx.code_source ?? '-'} · 로그 ${ctx.log_count}건 조회`,
    },
  ],
});

const mention = ctx.severity === 'critical' ? '<!here> ' : '';
return {
  json: {
    slack: {
      text: `${mention}${sev.icon} [${sev.label}] ${ctx.alertname} — ${ctx.annotations.summary ?? ''}`,
      blocks,
    },
  },
};
